import json,os,subprocess,shutil,platform
from pathlib import Path
out={'hostname':platform.node(),'uid':os.getuid(),'sbin_tools':{name:Path('/usr/sbin',name).exists() for name in ('nft','iptables','ip')}}
for name,args in {'sudo':['sudo','-n','true'],'nfs_units':['systemctl','show','srv-mlnfs-inputs.mount','ml-nfs-ready.service','--no-pager','-p','ActiveState','-p','Result','-p','What','-p','Where'],'ip':['ip','-j','address','show']}.items():
 p=subprocess.run(args,capture_output=True,text=True,timeout=8);out[name]={'returncode':p.returncode,'stdout':p.stdout,'stderr':p.stderr}
print(json.dumps(out))
